\label{Main3}
	Let $\mathcal{G}_\Gamma$ be a graph product of cyclic groups and let $\chi:\mathcal{G}_\Gamma\to\mathbb{R}$ be a non-zero character. Then:
	\begin{enumerate}
		\item $[\chi]\in\Sigma^n(\mathcal{G}_\Gamma,\mathbb{Z})$ if and only if $\chi$ satisfies the homological $n$-link condition.
		\item If $ [\chi]\in\Sigma^n(\mathcal{G}_\Gamma)$, then $\chi$ satisfies the homotopical $n$-link condition.
	\end{enumerate}

\label{Main4}
	Let $\mathcal{G}_\Gamma$ be a graph product of cyclic groups with
	$V(\Gamma^{<\infty})=\{v\}$. Then
	$$\beta_1^{(2)}(\operatorname{Aut}(\mathcal{G}_\Gamma))\neq 0
	\quad \text{if and only if} \quad
	\mathcal{G}_\Gamma \in
	\bigl\{
	\mathbb{Z}^2\times \mathbb{Z}/o(v)\mathbb{Z},
	\mathbb{Z}\ast \mathbb{Z}/o(v)\mathbb{Z}
	\bigr\}.$$

\label{teo:FinitenesSigma}
	Let $G$ be a group of type $\mathrm{F}_n$ and $G'\leq N\leq G$. Then:
	\begin{enumerate}
		\item[(i)] $N$ is of type $\mathrm{FP}_n$ if and only if $\{[\chi]\in S(G)\mid \chi(N)=0\}\subseteq \Sigma^n(G,\mathbb{Z})$.
		\item[(ii)] $N$ is of type $\mathrm{F}_n$ if and only if
		$\{[\chi]\in S(G)\mid \chi(N)=0\}\subseteq \Sigma^n(G)$.
	\end{enumerate}

\label{teo:MMVW}
	Let $X$ be a $G$–CW–complex with cocompact $n$-skeleton, and let $\chi:G\to\mathbb{R}$ be a character such that for every $p$-cell $\sigma$ of $X$ with $p\leq n$, we have $G_\sigma\nsubseteq\ker(\chi)$, where $G_\sigma$ denotes the stabilizer of $\sigma$. Then:
	\begin{itemize}
		\item[(i)] If $X$ is $(n-1)$-connected and $[\chi|_{G_\sigma}]\in\Sigma^{\,n-p}(G_\sigma)$ for each $p$-cell $\sigma$ with $p\leq n$, then $[\chi]\in\Sigma^n(G)$.

		\item[(ii)] If $X$ is $(n-1)$-acyclic and $[\chi|_{G_\sigma}]\in\Sigma^{\,n-p}(G_\sigma,\mathbb{Z})$ for each $p$-cell $\sigma$ with $p\leq n$, then $[\chi]\in\Sigma^n(G,\mathbb{Z})$.
	\end{itemize}

Let $\mathcal{G}_\Gamma$ be a graph product of cyclic groups. Then:
	\begin{enumerate}
		\item Let $\Delta$ be an \textbf{induced subgraph} of $\Gamma$; that is, a subgraph such that whenever $v,w\in V(\Delta)$ satisfy ${v,w}\in E(\Gamma)$, then ${v,w}\in E(\Delta)$. The subgroup of $\mathcal{G}_\Gamma$ generated by $V(\Delta)$ is isomorphic to $\mathcal{G}_\Delta$. Such subgroups are called \textbf{special subgroups}.
		\item The centre $\mathrm{Z}(\mathcal{G}_\Gamma)$ of $\mathcal{G}_\Gamma$ is the special subgroup $\mathcal{G}_\Delta$, where $\Delta$ is the subgraph induced by the vertices $v\in V(\Gamma)$ satisfying $\mathrm{st}(v)=\Gamma$.
		\item A special subgroup $\mathcal{G}_\Delta$ is finite if and only if $\Delta$ is complete and each vertex group has finite order.
	\end{enumerate}

\label{GeneratorsAUT}
	Let $\mathcal{G}_\Gamma$ be a graph product of cyclic groups. Then $\mathrm{Aut}(\mathcal{G}_\Gamma)$ is generated by the following types of automorphisms:
	\begin{itemize}
		\item \textbf{Labelled graph automorphisms:} every automorphism of $\Gamma$ preserving vertex labels induces an automorphism of $\mathcal{G}_\Gamma$.
		\item \textbf{Factor automorphisms:} every automorphism of an individual vertex group extends to an automorphism of $\mathcal{G}_\Gamma$.
		\item \textbf{Transvections:} for $u,v\in V(\Gamma)$, define $\tau^v_u$ as follows:
		\begin{itemize}
			\item If $\mathrm{lk}(u)\subset\mathrm{st}(v)$ and $o(u)=\infty$, set $\tau^v_u(u)=uv$ and fix all other generators.
			\item If $\mathrm{st}(u)\subset\mathrm{st}(v)$ and there exists a prime $p$ such that $o(u)=p^i$ and $o(v)=p^j$, define $\tau^v_u(u)=uv^k$, where $k=\max\{1,p^{j-i}\}$.
		\end{itemize}
		\item \textbf{Partial conjugations:} if $v\in V(\Gamma)$ and $\Gamma\setminus\mathrm{st}(v)\neq\emptyset$, and $C$ is a connected component of $\Gamma\setminus\mathrm{st}(v)$, define $\pi^v_C$ by
		$$\pi^v_C(w)=
		\begin{cases}
			vwv^{-1}, & \text{if } w\in V(C),\\[2pt]
			w, & \text{otherwise.}
		\end{cases}$$
	\end{itemize}

