The following families of groups satisfy the Atiyah conjecture:
	\begin{enumerate}
		\item Locally indicable groups. \cite[Jaikin-Zapirain-López-Álvarez]{Jaikin-Lopez 2020} 
		\item RFRS groups. \cite[Kielak]{Kielak}
	\end{enumerate}

\label{Derivation Lemma}
	Let $G$ be a torsion-free group satisfying the Atiyah conjecture and $f\in  \mathrm{Der}(T_\Gamma,\mathcal{D}(T_\Gamma))$.
	\begin{enumerate}
		\item If $u,v\in G$ are such that $uv=vu$ then $(1-v)^{-1}f(v)=(1-u)^{-1}f(u)$.
		\item f $u,v\in G$ are such that $uvu=v$ then $(1-v)^{-1}f(v)=(1-u)^{-1}f(u)$.
	\end{enumerate}

\label{Type 1}
	There are $o(u_1)o(u_2)$ connected components in $\Delta$ for each connected component of $\Gamma_{u_1u_2}$ of Type $1$. Hence, Type $1$ connected components contribute
	$o(u_1)o(u_2)\beta_1^{(2)}(A_\Gamma)$ dimensions to $\mathrm{Der}\bigl(\ker(\varphi),\mathcal{D}(\ker(\varphi))\bigr)$.

\label{Type4}
	Let $f\in \mathrm{Der}\bigl(\ker(\varphi),\mathcal{D}(\ker(\varphi))\bigr)$. Assume that $v_{i_1,i_2}$ and $v_{i_1+1,i_2}$ lie in the same connected component of $\Delta$ and that $\{v,u_1\}\in E(\Gamma)$. Then $(1-X_{i_1,i_2})^{-1}f(X_{i_1,i_2})=(1-v_{i_1,i_2})^{-1}f(v_{i_1,i_2})$. As a consequence Type $4$ connected components plus all generators of the form $X_{i,j}$ contribute to
	$1$ dimension to $\mathrm{Der}\bigl(\ker(\varphi),\mathcal{D}(\ker(\varphi))\bigr)$.

\label{Type 2}
	Type $2$ connected components contribute $o(u_2)\bigl(\beta_1^{(2)}(A_{\Gamma_{u_1}})-\beta_1^{(2)}(A_\Gamma)\bigr)$
	dimensions to $\mathrm{Der}\bigl(\ker(\varphi),\mathcal{D}(\ker(\varphi))\bigr)$.

Let $\mathcal{G}_\Gamma$ be a RAAG and let $\chi:\mathcal{G}_\Gamma\to\mathbb{R}$ be a character.
	\begin{itemize}
		\item $\chi$ satisfies the \textbf{homological $n$-link condition} if $\widehat{\mathrm{lk}_{\mathrm{Liv}^\chi}(\Delta)}$ is $(n-\left|V(\Delta)\right|-1)$-acyclic for every clique $\Delta\subset\Gamma\setminus\mathrm{Liv}^\chi$ with $\left|V(\Delta)\right|\leq n$.
		\item $\chi$ satisfies the \textbf{homotopical $n$-link condition} if $\widehat{\mathrm{lk}_{\mathrm{Liv}^\chi}(\Delta)}$ is $(n-\left|V(\Delta)\right|-1)$-acyclic for every clique $\Delta\subset\Gamma\setminus\mathrm{Liv}^\chi$ with $\left|V(\Delta)\right|\leq n$ and $\widehat{\mathrm{Liv}^\chi}$ is $(n-1)$-connected.	
		\item $\chi$ satisfies the \textbf{strong homotopical $n$-link condition}  if $\widehat{\mathrm{lk}_{\mathrm{Liv}^\chi}(\Delta)}$ is $(n-\left|V(\Delta)\right|-1)$-connected for every clique $\Delta\subset\Gamma\setminus\mathrm{Liv}^\chi$ with $\left|V(\Delta)\right|\leq n$.
	\end{itemize}

\label{SigmaRAAG}
	Let $A_\Gamma$ be a RAAG and let $\chi:A_\Gamma\to\mathbb{R}$ be a character. Then:
	\begin{enumerate}
		\item $[\chi]\in\Sigma^n(A_\Gamma,\mathbb{Z})$ if and only if $\chi$ satisfies the homological $n$-link condition.
		\item $[\chi]\in\Sigma^n(A_\Gamma)$ if and only if $\chi$ satisfies the homotopical $n$-link condition.
	\end{enumerate}

