By Proposition~\ref{FiniteAut}, the group $\mathrm{Aut}(\mathcal{G}_\Gamma)$ is finite if and only if $\Gamma$ is a complete graph on two or three vertices. Hence we may assume that we are not in these cases.

	Consider the short exact sequence
	$$1 \longrightarrow \mathcal{G}_\Gamma/\mathrm{Z}(\mathcal{G}_\Gamma)
	\longrightarrow \mathrm{Aut}(\mathcal{G}_\Gamma)
	\longrightarrow \mathrm{Out}(\mathcal{G}_\Gamma)
	\longrightarrow 1.$$
	If $\mathcal{G}_\Gamma/\mathrm{Z}(\mathcal{G}_\Gamma)$ is finite, then $\mathcal{G}_\Gamma=\mathrm{Z}(\mathcal{G}_\Gamma)$, so 
	$\mathcal{G}_\Gamma \cong \mathbb{Z}^k\times  \mathbb{Z}/o(v)\mathbb{Z}\times \mathbb{Z}/o(u)\mathbb{Z}$. 
	In this case $\mathrm{Aut}(\mathbb{Z}^k)$ embeds as a finite-index subgroup of $\mathrm{Aut}(\mathbb{Z}^k\times  \mathbb{Z}/o(v)\mathbb{Z}\times \mathbb{Z}/o(u)\mathbb{Z})$, and 
	$\beta_1^{(2)}(\mathrm{Aut}(\mathbb{Z}^k))\neq 0$ if and only if $k=2$.

	If both $\mathcal{G}_\Gamma/\mathrm{Z}(\mathcal{G}_\Gamma)$ and $\mathrm{Out}(\mathcal{G}_\Gamma)$ are infinite, then by \cite[Theorem~7.2~(7)]{Luck} we have $\beta_1^{(2)}(\mathrm{Aut}(\mathcal{G}_\Gamma))=0$. 
	Therefore, we may assume that $\mathrm{Out}(\mathcal{G}_\Gamma)$ is finite, so that $\mathcal{G}_\Gamma/\mathrm{Z}(\mathcal{G}_\Gamma)$ has finite index in $\mathrm{Aut}(\mathcal{G}_\Gamma)$.

	If $\mathrm{Z}(\mathcal{G}_\Gamma)\neq 1$, then $\mathrm{Z}(\mathcal{G}_\Gamma)\in\{\mathcal{G}_v,\mathcal{G}_u,\mathcal{G}_{u,v}\}$; otherwise, by condition~(3) of Proposition~\ref{FiniteOut}, $\mathrm{Out}(\mathcal{G}_\Gamma)$ would be infinite. Moreover, the centre being non-trivial implies that $\Gamma$ is connected.
	\begin{itemize}
		\item If $\mathrm{Z}(\mathcal{G}_\Gamma)=\mathcal{G}_v$ then $\mathcal{G}_\Gamma/\mathrm{Z}(\mathcal{G}_\Gamma)\cong \mathcal{G}_{\Gamma_v}$ and by Theorem~\ref{BettiClique} $\beta_1^{(2)}(\mathcal{G}_{\Gamma_v})=0$ if and only if $\Gamma_v$ and $\Gamma_{u,v}$ are connected. $\Gamma$ and $\Gamma_u$ are connected, so if $\Gamma_v$ is connected then by Lemma \ref{Disconnected2}.3 $\Gamma_{u,v}$ must be connected. Hence, $\beta_1^{(2)}(\operatorname{Aut}(\mathcal{G}_\Gamma))\neq 0$ implies $\Gamma_v$ is disconnected. Applying Lemma \ref{Gamma connected}.1 it follows that $\mathcal{G}_{\Gamma_v}\cong\mathbb{Z}\ast\mathbb{Z}/o(u)\mathbb{Z}$ and thus $\Gamma$ is the graph $\begin{tikzpicture}[main/.style = {draw, circle},node distance={15mm}] 
			\node[][main] (1)  {}; 
			\node[label={$v$}][main] (2) [right of=1] {};
			\node[label={$u$}][main] (3) [right of=2] {}; 
			\draw[-] (1) -- (2);
			\draw[-] (2) -- (3);
		\end{tikzpicture}$.
		\item If  $\mathrm{Z}(\mathcal{G}_\Gamma)=\mathcal{G}_u$ it follows in the same way as the previous case that $\begin{tikzpicture}[main/.style = {draw, circle},node distance={15mm}] 
			\node[][main] (1)  {}; 
			\node[label={$u$}][main] (2) [right of=1] {};
			\node[label={$v$}][main] (3) [right of=2] {}; 
			\draw[-] (1) -- (2);
			\draw[-] (2) -- (3);
		\end{tikzpicture}$.
		\item If $\mathrm{Z}(\mathcal{G}_\Gamma)=\mathcal{G}_{u,v}$ then  $\mathcal{G}_\Gamma/\mathrm{Z}(\mathcal{G}_\Gamma)\cong A_{\Gamma_{u,v}}$, so $\beta_1^{(2)}(\operatorname{Aut}(\mathcal{G}_\Gamma))\neq 0$ if and only if $\Gamma_{u,v}$ is disconnected. But $\Gamma,\Gamma_u,\Gamma_v$ connected and $\Gamma_{u,v}$ disconnected implies by Lemma \ref{LemmaDisconnected} that $\mathrm{Z}(\mathcal{G}_\Gamma)=1$, contradiction.
	\end{itemize}
	If $\mathrm{Z}(\mathcal{G}_\Gamma)=1$, then $\mathcal{G}_\Gamma$ has finite index in $\mathrm{Aut}(\mathcal{G}_\Gamma)$. 
	By Theorem~\ref{BettiClique}, $\beta_1^{(2)}(\mathcal{G}_\Gamma)=0$ if and only if $\Gamma,\Gamma_u,\Gamma_v$ and $\Gamma_{u,v}$ are connected. 
	Thus, by Lemma~\ref{Disconnected2}, we deduce that $\beta_1^{(2)}(\mathrm{Aut}(\mathcal{G}_\Gamma))=0$ unless $\mathcal{G}_\Gamma$ is one of the groups in the statement.
